import { z } from 'zod';
import rawModel from './model.json';

// Serving side of the skip-risk model trained in ml/ (see
// ml/SKIP_RISK_MODEL_CARD.md). model.json is generated by
// `uv run growthtracker-ml train`; don't edit it by hand. The features mirror
// ml/src/growthtracker_ml/skiprisk/features.py line for line, and
// tests/skip-risk-logic.test.ts checks both give the same answers.

export const FEATURES = [
  'intercept', 'band_early', 'band_afternoon', 'band_evening', 'band_late', 'weekend', 'log_duration',
  'log_lead_days', 'day_load', 'has_goal', 'personal_logit', 'band_deviation', 'goal_deviation', 'recent_misses',
] as const;
const NO_GOAL = '__none__';

const modelSchema = z.object({
  name: z.literal('skip-risk'),
  features: z.array(z.string()),
  coefficients: z.array(z.number()),
  shrinkage: z.object({
    priorMean: z.number().gt(0).lt(1),
    userStrength: z.number().positive(),
    bandStrength: z.number().positive(),
    goalStrength: z.number().positive(),
    historyLimit: z.number().int().positive(),
  }),
  threshold: z.number().gt(0).lt(1),
  minHistory: z.number().int().nonnegative(),
  resolveHours: z.number().nonnegative(),
  bands: z.array(z.object({ name: z.string(), startMinutes: z.number().int() })),
  clamps: z.object({
    minDuration: z.number().positive(),
    maxDuration: z.number().positive(),
    maxLeadDays: z.number().positive(),
    maxDayLoad: z.number().int().nonnegative(),
    recent: z.number().int().positive(),
  }),
  metadata: z.looseObject({ version: z.string() }),
});

export type SkipRiskModel = z.infer<typeof modelSchema>;

export function loadModel(raw: unknown): SkipRiskModel {
  const model = modelSchema.parse(raw);
  if (model.features.join() !== FEATURES.join() || model.coefficients.length !== FEATURES.length) {
    throw new Error(`Skip-risk model features [${model.features}] don't match this code's [${FEATURES}]`);
  }
  if (model.bands.map(b => b.name).join() !== 'early,morning,afternoon,evening,late' || model.bands[0].startMinutes !== 0) {
    throw new Error('Skip-risk model bands don\'t match this code');
  }
  return model;
}

// Checked once at startup, so a bad model.json fails the deploy, not a request.
export const MODEL = loadModel(rawModel);

export type Band = 'early' | 'morning' | 'afternoon' | 'evening' | 'late';

export interface BlockInput {
  /** Local start time, minutes after midnight. */
  startMinutes: number;
  /** Local weekday, 0 = Sunday. */
  weekday: number;
  durationMinutes: number;
  /** Start minus when it was planned. */
  leadHours: number;
  /** The person's other blocks that local day. */
  dayLoad: number;
  goalId: string | null;
}

export interface Outcome {
  band: Band;
  goalId: string | null;
  missed: boolean;
}

const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max);
const logit = (p: number) => Math.log(p / (1 - p));

export function bandOf(model: SkipRiskModel, startMinutes: number): Band {
  let band = model.bands[0].name;
  for (const b of model.bands) {
    if (startMinutes >= b.startMinutes) band = b.name;
  }
  return band as Band;
}

const sum = (outcomes: Outcome[]) => outcomes.reduce((n, o) => n + (o.missed ? 1 : 0), 0);

/** Shrunken skip rates from the person's most recent outcomes (most recent first). */
export function personalStats(model: SkipRiskModel, history: readonly Outcome[], band: Band, goalId: string | null) {
  const s = model.shrinkage;
  const recent = history.slice(0, s.historyLimit);
  const n = recent.length;
  const misses = sum(recent);
  const userRate = (misses + s.userStrength * s.priorMean) / (n + s.userStrength);

  const sameBand = recent.filter(o => o.band === band);
  const bandRate = (sum(sameBand) + s.bandStrength * userRate) / (sameBand.length + s.bandStrength);

  const key = goalId || NO_GOAL;
  const sameGoal = recent.filter(o => (o.goalId || NO_GOAL) === key);
  const goalRate = (sum(sameGoal) + s.goalStrength * userRate) / (sameGoal.length + s.goalStrength);

  const last = recent.slice(0, model.clamps.recent);
  return {
    n,
    misses,
    userRate,
    bandRate,
    goalRate,
    bandN: sameBand.length,
    goalN: sameGoal.length,
    recentMisses: last.length ? sum(last) / last.length : 0,
  };
}

export function featureVector(model: SkipRiskModel, block: BlockInput, history: readonly Outcome[]): number[] {
  const c = model.clamps;
  const band = bandOf(model, block.startMinutes);
  const stats = personalStats(model, history, band, block.goalId);
  const duration = clamp(block.durationMinutes, c.minDuration, c.maxDuration);
  const leadDays = Math.min(Math.max(block.leadHours, 0) / 24, c.maxLeadDays);
  const user = logit(stats.userRate);
  return [
    1,
    band === 'early' ? 1 : 0,
    band === 'afternoon' ? 1 : 0,
    band === 'evening' ? 1 : 0,
    band === 'late' ? 1 : 0,
    block.weekday === 0 || block.weekday === 6 ? 1 : 0,
    Math.log(duration / 60),
    Math.log1p(leadDays),
    clamp(block.dayLoad, 0, c.maxDayLoad),
    block.goalId ? 1 : 0,
    user,
    logit(stats.bandRate) - user,
    logit(stats.goalRate) - user,
    stats.recentMisses,
  ];
}

export function skipProbability(model: SkipRiskModel, block: BlockInput, history: readonly Outcome[]): number {
  const x = featureVector(model, block, history);
  const z = model.coefficients.reduce((total, c, i) => total + c * x[i], 0);
  return 1 / (1 + Math.exp(-z));
}

const BAND_WORDS: Record<Band, string> = {
  early: 'early-morning', morning: 'morning', afternoon: 'afternoon', evening: 'evening', late: 'late-night',
};

/**
 * Up to two plain reasons behind a high risk: the parts of the score that push
 * it up most, compared with a neutral block (a weekday morning hour, planned
 * the same day, on a free day, for someone with an average record).
 */
export function reasons(model: SkipRiskModel, block: BlockInput, history: readonly Outcome[]): string[] {
  const x = featureVector(model, block, history);
  const w = model.coefficients;
  const band = bandOf(model, block.startMinutes);
  const stats = personalStats(model, history, band, block.goalId);
  const neutralPersonal = logit(model.shrinkage.priorMean);
  const lead = Math.round(Math.max(block.leadHours, 0) / 24);
  const candidates: Array<[number, string]> = [
    [w[1] * x[1] + w[2] * x[2] + w[3] * x[3] + w[4] * x[4] + w[11] * x[11],
      stats.bandN >= 3 ? `You often miss ${BAND_WORDS[band]} blocks` : `${BAND_WORDS[band][0].toUpperCase()}${BAND_WORDS[band].slice(1)} blocks are often missed`],
    [w[10] * (x[10] - neutralPersonal), `You've missed ${stats.misses} of your last ${stats.n} blocks`],
    [w[12] * x[12], 'Blocks for this goal often slip'],
    [w[13] * x[13], 'Your last few blocks were missed'],
    [w[6] * x[6], `It's a long block (${Math.round(block.durationMinutes)} min)`],
    [w[7] * x[7], `Planned ${lead} ${lead === 1 ? 'day' : 'days'} ahead`],
    [w[8] * x[8], `${block.dayLoad} other ${block.dayLoad === 1 ? 'block' : 'blocks'} that day`],
    [w[5] * x[5], "It's at the weekend"],
  ];
  return candidates.filter(([effect]) => effect > 0.1).sort((a, b) => b[0] - a[0]).slice(0, 2).map(([, text]) => text);
}
